/// xorshift64*, duplicated bit-for-bit from the C++ driver so both sides add
/// the same noise to the same symbols.
struct Rng(u64);

impl Rng {
    fn next_u64(&mut self) -> u64 {
        let mut x = self.0;
        x ^= x >> 12;
        x ^= x << 25;
        x ^= x >> 27;
        self.0 = x;
        x.wrapping_mul(0x2545_F491_4F6C_DD1D)
    }
    fn unit(&mut self) -> f32 {
        (self.next_u64() >> 40) as f32 / (1u32 << 24) as f32
    }
    fn normal(&mut self) -> f32 {
        let u1 = self.unit().max(1e-7);
        let u2 = self.unit();
        (-2.0 * u1.ln()).sqrt() * (std::f32::consts::TAU * u2).cos()
    }
}

#[test]
fn transmit_matches_freedv_gui_bit_for_bit() {
    for (call, want) in TX_VECTORS {
        let mut got = [0.0f32; EOO_FLOATS];
        text::encode(call, &mut got);
        for (i, (g, w)) in got.iter().zip(want.iter()).enumerate() {
            assert_eq!(
                g, w,
                "callsign {call:?}: EOO float {i} is {g}, the C++ reference emits {w}"
            );
        }
    }
}

#[test]
fn receive_recovers_what_the_reference_recovers() {
    for (call, sigma, seed, want) in RX_VECTORS {
        let mut buf = [0.0f32; EOO_FLOATS];
        text::encode(call, &mut buf);
        let mut rng = Rng(seed);
        for v in buf.iter_mut() {
            *v += sigma * rng.normal();
        }
        // The reference reports an empty string both when the frame failed to
        // decode and when it decoded but carried no callsign; `text::decode`
        // collapses both to `None`, since either way there is nothing to
        // report.
        let got = text::decode(&buf);
        let want = (!want.is_empty()).then_some(want);
        assert_eq!(got.as_deref(), want, "callsign {call:?} at sigma {sigma} seed {seed:#x}");
    }
}

#[test]
fn the_vector_set_covers_both_sides_of_the_waterfall() {
    // A guard on the fixture itself: if a regeneration ever produced vectors
    // that all decode (or all fail), the test above would still pass while
    // proving much less.
    let recovered = RX_VECTORS.iter().filter(|(_, _, _, got)| !got.is_empty()).count();
    assert!(recovered > 0, "no vector decodes — the fixture proves nothing");
    assert!(recovered < RX_VECTORS.len(), "every vector decodes — no failure case covered");
}
